+func (p *Plane) StepLine() (string, time.Time) {
+	p.mu.Lock()
+	ms := make([]*machine, 0, len(p.ms))
+	for _, m := range p.ms {
+		ms = append(ms, m)
+	}
+	p.mu.Unlock()
